 60	    private static void bfsComponent(Graph graph, int source, boolean[] visited, List<Integer> result) {
 61	        Deque<Integer> queue = new ArrayDeque<>();
 62	        visited[source] = true;
 63	        queue.addLast(source);
 64	
 65	        while (!queue.isEmpty()) {
 66	            int current = queue.removeFirst();
 67	            result.add(current);
 68	
 69	            for (int neighbor : graph.neighbors(current)) {
 70	                if (!visited[neighbor]) {
 71	                    visited[neighbor] = true;
 72	                    queue.addLast(neighbor);
 73	                }
 74	            }
 75	        }
 76	    }
 77	
 78	    public static List<Integer> bfs(Graph graph) {
 79	        Objects.requireNonNull(graph, "graph");
 80	
 81	        int vertexCount = graph.vertexCount();
 82	        boolean[] visited = new boolean[vertexCount];
 83	        List<Integer> result = new ArrayList<>(vertexCount);
 84	
 85	        for (int vertex = 0; vertex < vertexCount; vertex++) {
 86	            if (!visited[vertex]) {
 87	                bfsComponent(graph, vertex, visited, result);
 88	            }
 89	        }
 90	        return result;
 91	    }
